const dashboard = global.get("dashboardV1");
if (!dashboard || typeof dashboard.buildDeviceDeleteQuery !== "function") {
    msg.statusCode = 500;
    msg.payload = { ok: false, error: "dashboard_helper_missing", message: "dashboard helper missing" };
    return [null, msg];
}

function readPayloadObject(message) {
    const candidates = [
        message.payload,
        message.req && message.req.body
    ];

    for (const candidate of candidates) {
        if (candidate && typeof candidate === "object" && !Buffer.isBuffer(candidate)) {
            return candidate;
        }

        const text = Buffer.isBuffer(candidate)
            ? candidate.toString("utf8")
            : typeof candidate === "string"
                ? candidate
                : "";
        const trimmed = text.trim();
        if (!trimmed) {
            continue;
        }

        try {
            const parsed = JSON.parse(trimmed);
            if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
                return parsed;
            }
        } catch (error) {
            // Ungueltiges JSON wird unten als fehlende device_id sauber abgelehnt.
        }
    }

    return {};
}

const payload = readPayloadObject(msg);
const deviceId = typeof payload.device_id === "string" ? payload.device_id.trim() : "";
if (!deviceId) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "device_id_required", message: "device_id is required" };
    return [null, msg];
}

if (payload.confirm_delete !== true) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "delete_not_confirmed", message: "delete confirmation is required" };
    return [null, msg];
}

const deleteQuery = dashboard.buildDeviceDeleteQuery(deviceId);
if (!deleteQuery) {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "invalid_device_id", message: "device_id is invalid" };
    return [null, msg];
}

msg.deleteDeviceId = deviceId;
msg.deleteDeviceResponse = { ok: true, device_id: deviceId, message: "device deleted" };
msg.topic = deleteQuery;
return [msg, null];

const deviceId = msg.deleteDeviceId || "";
const runtime = global.get("smarthome_runtime");
if (deviceId && runtime && runtime.devices && Object.prototype.hasOwnProperty.call(runtime.devices, deviceId)) {
    delete runtime.devices[deviceId];
    global.set("smarthome_runtime", runtime);
}

const clearRetainedMessages = deviceId
    ? ["meta", "availability", "state", "event", "ack"].map((block) => ({
        topic: "smarthome/device/" + deviceId + "/" + block,
        payload: "",
        qos: 0,
        retain: true
    }))
    : [];

msg.statusCode = 200;
msg.payload = msg.deleteDeviceResponse || { ok: true, device_id: deviceId, message: "device deleted" };
return [msg, clearRetainedMessages];
